"""Install PetroNet launch/setup files only. Run from the krk_gas repository root."""
from pathlib import Path
import json
import subprocess
import sys

FILES = json.loads('{"app.py": "\\"\\"\\"Repository-root entry point. Run: streamlit run app.py\\"\\"\\"\\nimport os\\nimport runpy\\nimport sys\\nfrom pathlib import Path\\n\\nimport streamlit as st\\n\\nROOT = Path(__file__).resolve().parent\\nsys.path.insert(0, str(ROOT))\\nfrom scripts.prepare_dashboard import DATABASE, PROJECT, check_database\\n\\nready, message = check_database()\\nif not ready:\\n    st.error(\\"ฐานข้อมูลยังไม่พร้อมสำหรับ Dashboard\\")\\n    st.write(message)\\n    st.write(\\"หยุดแอปด้วย Ctrl+C แล้วรันคำสั่งนี้จากโฟลเดอร์หลักของ repository\\")\\n    st.code(\\"python scripts/prepare_dashboard.py\\", language=\\"bash\\")\\n    st.write(\\"เมื่อขึ้น READY ให้รัน streamlit run app.py อีกครั้ง\\")\\n    st.stop()\\n\\n# This launcher deliberately uses the database built for this repository.\\nos.environ[\\"GAS_DW_PATH\\"] = str(DATABASE.resolve())\\nrunpy.run_path(str(PROJECT / \\"app.py\\"), run_name=\\"__main__\\")\\n", "DASHBOARD_QUICKSTART.md": "# เปิด PetroNet Dashboard\\n\\n## GitHub Codespaces\\n\\n1. เลือก branch `krk_gas` แล้วสร้าง Codespace ใหม่ หรือใช้คำสั่ง `Codespaces: Rebuild Container` ใน Codespace เดิม\\n2. รอขั้นตอนเตรียมระบบจนแสดง `READY` ระบบจะติดตั้ง dependencies โหลด CSV และรัน dbt build\\n3. เปิด Terminal ใหม่ที่โฟลเดอร์หลัก `Gasstation-KrK` แล้วรัน:\\n\\n```bash\\nstreamlit run app.py\\n```\\n\\n4. เปิดแท็บ Ports เลือก 8501 แล้ว Open in Browser\\n\\nการเปิด Codespace เดิมอีกครั้งไม่จำเป็นต้องโหลดข้อมูลใหม่ เปิด Terminal ใหม่และใช้คำสั่งข้างต้นได้ ถ้าแก้ CSV หรือโมเดล SQL ให้หยุดแอปแล้วรัน `python scripts/prepare_dashboard.py` ก่อน\\n\\n## ใช้ environment ที่เปิดอยู่แล้ว\\n\\nจากโฟลเดอร์หลักของ repository:\\n\\n```bash\\npython -m pip install -r requirements-dashboard.txt\\npython scripts/prepare_dashboard.py\\nstreamlit run app.py\\n```\\n\\nให้ทำทีละคำสั่งและหยุดเมื่อมี error Python ที่ใช้ทดสอบคือ 3.12 ต้องเชื่อมต่ออินเทอร์เน็ตเพื่อติดตั้ง dependencies และ dbt packages\\n\\n## ฐานข้อมูลและขอบเขต\\n\\nตัวเรียกแอปที่ root ใช้ `Gasstation_dw_duckdb/dev.duckdb` โดยไม่ต้องตั้งพาธส่วนตัว SQL และ Dashboard เดิมไม่ถูกแก้ไข การเตรียมฐานข้อมูลใช้ไฟล์ชั่วคราว ตรวจ dbt build ให้ผ่านก่อนแทนไฟล์จริง และสำรองฐานข้อมูลก่อนหน้าเป็น `dev.duckdb.before-dashboard-setup`\\n\\nรันซ้ำเมื่อข้อมูลและโมเดลไม่เปลี่ยนจะข้ามการ build ถ้าเตรียมไม่สำเร็จให้แก้สาเหตุใน Terminal ก่อนเปิด Dashboard ไม่ต้องสร้างตารางเปล่า ไม่ต้อง commit ฐานข้อมูลหรือ virtual environment\\n\\nตรวจความพร้อมโดยไม่แก้ข้อมูล:\\n\\n```bash\\npython scripts/prepare_dashboard.py --check\\n```\\n\\nการเปิด Dashboard สำเร็จยืนยันการทำงานของระบบ ไม่ได้แก้ข้อจำกัดของสูตรหรือข้อมูลทางธุรกิจเดิม\\n", "requirements-dashboard.txt": "streamlit==1.63.0\\nduckdb==1.5.5\\npandas==3.0.5\\nplotly==7.0.0\\ndbt-core==1.12.4\\ndbt-duckdb==1.11.0\\n", ".devcontainer/devcontainer.json": "{\\n  \\"name\\": \\"PetroNet Dashboard\\",\\n  \\"image\\": \\"mcr.microsoft.com/devcontainers/python:1-3.12-bookworm\\",\\n  \\"workspaceFolder\\": \\"/workspaces/${localWorkspaceFolderBasename}\\",\\n  \\"postCreateCommand\\": \\"bash scripts/setup_codespace.sh\\",\\n  \\"remoteEnv\\": {\\n    \\"PATH\\": \\"${containerWorkspaceFolder}/.dashboard-venv/bin:${containerEnv:PATH}\\"\\n  },\\n  \\"forwardPorts\\": [8501],\\n  \\"portsAttributes\\": {\\n    \\"8501\\": {\\"label\\": \\"PetroNet Dashboard\\", \\"onAutoForward\\": \\"notify\\"}\\n  },\\n  \\"customizations\\": {\\n    \\"vscode\\": {\\n      \\"settings\\": {\\n        \\"python.defaultInterpreterPath\\": \\"${workspaceFolder}/.dashboard-venv/bin/python\\",\\n        \\"terminal.integrated.cwd\\": \\"${workspaceFolder}\\"\\n      }\\n    }\\n  }\\n}\\n", ".streamlit/config.toml": "[server]\\naddress = \\"0.0.0.0\\"\\nport = 8501\\nheadless = true\\n\\n[browser]\\ngatherUsageStats = false\\n", "scripts/prepare_dashboard.py": "\\"\\"\\"Prepare a local warehouse from committed CSV/SQL without editing business SQL.\\"\\"\\"\\nfrom pathlib import Path\\nimport argparse\\nimport hashlib\\nimport json\\nimport os\\nimport shutil\\nimport subprocess\\nimport sys\\nimport tempfile\\n\\nROOT = Path(__file__).resolve().parents[1]\\nPROJECT = ROOT / \\"Gasstation_dw_duckdb\\"\\nDATABASE = PROJECT / \\"dev.duckdb\\"\\nSTATE = PROJECT / \\".dashboard-ready.json\\"\\nRAW = (\\"Customer\\", \\"Employee\\", \\"GasStation\\", \\"Product\\", \\"Invoice\\",\\n       \\"InvoiceDetail\\", \\"StorageTank\\", \\"InventoryTransaction\\")\\n\\ndef required_tables():\\n    return {f.stem for f in (PROJECT / \\"models/datawarehouse\\").glob(\\"*.sql\\")}\\n\\ndef check_database(path=DATABASE):\\n    import duckdb\\n    if not path.is_file():\\n        return False, \\"Database file is missing\\"\\n    try:\\n        with duckdb.connect(str(path), read_only=True) as con:\\n            found = {r[0] for r in con.execute(\\n                \\"select table_name from information_schema.tables where table_schema=\'main\'\\").fetchall()}\\n            missing = sorted(required_tables() - found)\\n            if missing:\\n                return False, \\"Missing tables: \\" + \\", \\".join(missing)\\n            for name in (\\"dim_gasstation\\", \\"dim_product\\", \\"dim_date\\", \\"fact_sales\\"):\\n                if con.execute(f\'SELECT COUNT(*) FROM main.\\"{name}\\"\').fetchone()[0] == 0:\\n                    return False, f\\"Empty required table: {name}\\"\\n        return True, \\"All warehouse tables are available\\"\\n    except Exception as error:\\n        return False, str(error)\\n\\ndef fingerprint():\\n    files = [ROOT / \\"requirements-dashboard.txt\\", Path(__file__), PROJECT / \\"dbt_project.yml\\", PROJECT / \\"packages.yml\\"]\\n    for directory in (\\"datasets\\", \\"models\\", \\"macros\\", \\"seeds\\", \\"snapshots\\"):\\n        files.extend(p for p in (PROJECT / directory).rglob(\\"*\\") if p.is_file())\\n    digest = hashlib.sha256()\\n    for file in sorted(files):\\n        digest.update(file.relative_to(ROOT).as_posix().encode())\\n        with file.open(\\"rb\\") as stream:\\n            for chunk in iter(lambda: stream.read(1024 * 1024), b\\"\\"):\\n                digest.update(chunk)\\n    return digest.hexdigest()\\n\\ndef build():\\n    import duckdb\\n    for name in RAW:\\n        file = PROJECT / \\"datasets\\" / f\\"{name}.csv\\"\\n        if not file.is_file():\\n            raise RuntimeError(f\\"Missing source CSV: {file}\\")\\n    signature = fingerprint()\\n    try:\\n        prior = json.loads(STATE.read_text(encoding=\\"utf-8\\"))\\n    except (OSError, ValueError):\\n        prior = {}\\n    ready, reason = check_database()\\n    if ready and prior.get(\\"fingerprint\\") == signature:\\n        print(\\"READY: warehouse is unchanged; no rebuild needed\\", flush=True)\\n        return\\n    print(\\"Preparing warehouse. Stop any running dashboard first.\\", flush=True)\\n    if Path(str(DATABASE) + \\".wal\\").exists():\\n        raise RuntimeError(\\"A dev.duckdb.wal file exists. Close database writers cleanly before preparing.\\")\\n    # A temporary database is built and tested before replacing the working database.\\n    with tempfile.TemporaryDirectory(prefix=\\".dashboard-build-\\", dir=PROJECT) as temp:\\n        stage = Path(temp)\\n        db = stage / \\"dev.duckdb\\"\\n        if DATABASE.exists():\\n            shutil.copy2(DATABASE, db)\\n        with duckdb.connect(str(db)) as con:\\n            con.execute(\\"BEGIN TRANSACTION\\")\\n            try:\\n                for name in RAW:\\n                    con.execute(f\'\'\'CREATE OR REPLACE TABLE main.\\"{name}\\" AS\\n                        SELECT * FROM read_csv(?, header=true, delim=\',\', all_varchar=true)\'\'\',\\n                        [str(PROJECT / \\"datasets\\" / f\\"{name}.csv\\")])\\n                    count = con.execute(f\'SELECT COUNT(*) FROM main.\\"{name}\\"\').fetchone()[0]\\n                    if count == 0:\\n                        raise RuntimeError(f\\"Source CSV has no rows: {name}\\")\\n                    print(f\\"Loaded {name}: {count:,} rows\\", flush=True)\\n                con.execute(\\"COMMIT\\")\\n            except Exception:\\n                con.execute(\\"ROLLBACK\\")\\n                raise\\n        (stage / \\"profiles.yml\\").write_text(\'\'\'Gasstation_dw_duckdb:\\n  target: dashboard\\n  outputs:\\n    dashboard:\\n      type: duckdb\\n      path: \\"{{ env_var(\'PETRONET_BUILD_DB\') }}\\"\\n      schema: main\\n      threads: 4\\n\'\'\', encoding=\\"utf-8\\")\\n        env = os.environ.copy()\\n        env.update(PETRONET_BUILD_DB=str(db.resolve()), DBT_SEND_ANONYMOUS_USAGE_STATS=\\"false\\")\\n        exe = Path(sys.executable).parent / (\\"dbt.exe\\" if os.name == \\"nt\\" else \\"dbt\\")\\n        if not exe.is_file():\\n            raise RuntimeError(\\"dbt is missing from this Python environment. Install requirements-dashboard.txt first.\\")\\n        for command in (\\"deps\\", \\"build\\"):\\n            args = [str(exe), command, \\"--project-dir\\", str(PROJECT), \\"--profiles-dir\\", str(stage),\\n                    \\"--log-path\\", str(stage / \\"logs\\")]\\n            if command == \\"build\\":\\n                args += [\\"--target-path\\", str(stage / \\"target\\")]\\n            subprocess.run(args, env=env, cwd=PROJECT, check=True)\\n        ready, reason = check_database(db)\\n        if not ready:\\n            raise RuntimeError(reason)\\n        # All dbt connections have closed; never publish a database with an outstanding WAL.\\n        if Path(str(db) + \\".wal\\").exists():\\n            raise RuntimeError(\\"Build database has an outstanding WAL; it was not published.\\")\\n        if DATABASE.exists():\\n            shutil.copy2(DATABASE, PROJECT / \\"dev.duckdb.before-dashboard-setup\\")\\n        os.replace(db, DATABASE)\\n        shutil.copy2(stage / \\"target/run_results.json\\", PROJECT / \\".dashboard-run-results.json\\")\\n        STATE.write_text(json.dumps({\\"fingerprint\\": signature, \\"database\\": DATABASE.name}, indent=2), encoding=\\"utf-8\\")\\n    print(\\"READY: run streamlit run app.py from the repository root\\", flush=True)\\n\\nif __name__ == \\"__main__\\":\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument(\\"--check\\", action=\\"store_true\\", help=\\"Check the database without rebuilding\\")\\n    args = parser.parse_args()\\n    try:\\n        if args.check:\\n            ok, message = check_database()\\n            print(message)\\n            sys.exit(0 if ok else 1)\\n        build()\\n    except Exception as error:\\n        print(f\\"SETUP FAILED: {error}\\", file=sys.stderr)\\n        sys.exit(1)\\n", "scripts/setup_codespace.sh": "#!/usr/bin/env bash\\nset -euo pipefail\\ncd \\"$(dirname \\"$0\\")/..\\"\\npython3 -m venv .dashboard-venv\\n.dashboard-venv/bin/python -m pip install -r requirements-dashboard.txt\\n.dashboard-venv/bin/python scripts/prepare_dashboard.py\\necho \\"READY: open a new terminal and run: streamlit run app.py\\"\\necho \\"In an existing terminal, first run: source .dashboard-venv/bin/activate\\"\\n", "scripts/__init__.py": "\\n"}')
root = Path.cwd().resolve()
if not (root / "Gasstation_dw_duckdb/app.py").is_file():
    sys.exit("STOP: run this file from the Gasstation-KrK repository root, not its subfolder.")
try:
    branch = subprocess.check_output(["git", "branch", "--show-current"], cwd=root, text=True).strip()
except (OSError, subprocess.CalledProcessError):
    sys.exit("STOP: Git repository not found.")
if branch != "krk_gas":
    sys.exit(f"STOP: current branch is {branch!r}. Switch to krk_gas first.")

# Preflight every destination before writing. Never overwrite a different existing file.
for name, content in FILES.items():
    path = root / name
    if not path.resolve().is_relative_to(root):
        sys.exit(f"STOP: destination outside repository: {name}")
    if path.exists() and (not path.is_file() or path.read_text(encoding="utf-8") != content):
        sys.exit(f"STOP: {name} already exists with different contents. No setup files were changed.")
for name, content in FILES.items():
    path = root / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8", newline="\n")
    print("Installed", name)

ignore = root / ".gitignore"
original = ignore.read_text(encoding="utf-8") if ignore.exists() else ""
patterns = [".dashboard-venv/", "**/.dashboard-build-*/", "**/.dashboard-ready.json",
            "**/.dashboard-run-results.json", "**/dev.duckdb.before-dashboard-setup",
            "**/*.duckdb", "**/*.duckdb.wal"]
missing = [p for p in patterns if p not in original.splitlines()]
if missing:
    with ignore.open("a", encoding="utf-8", newline="\n") as stream:
        stream.write("\n# PetroNet generated dashboard files\n" + "\n".join(missing) + "\n")
print("SUCCESS: setup files installed. Business SQL and the existing dashboard were not changed.")
print("Next: python -m pip install -r requirements-dashboard.txt")
print("Then: python scripts/prepare_dashboard.py")
print("After READY: streamlit run app.py")
